import{_ as p,r as s,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Updating Partials - October CMS - 4.x","titleTemplate":false,"description":"Learn more about the updating your content dynamically.","frontmatter":{"subtitle":"Learn more about the updating your content dynamically."},"headers":[{"level":2,"title":"Pulling Partial Updates","slug":"pulling-partial-updates","link":"#pulling-partial-updates","children":[{"level":3,"title":"Self-Updating Partials","slug":"self-updating-partials","link":"#self-updating-partials","children":[]},{"level":3,"title":"Global Partial Updates","slug":"global-partial-updates","link":"#global-partial-updates","children":[]}]},{"level":2,"title":"Update Definition","slug":"update-definition","link":"#update-definition","children":[{"level":3,"title":"Appending and Prepending Content","slug":"appending-and-prepending-content","link":"#appending-and-prepending-content","children":[]},{"level":3,"title":"Using Custom HTML Selectors","slug":"using-custom-html-selectors","link":"#using-custom-html-selectors","children":[]}]},{"level":2,"title":"Pushing Partial Updates","slug":"pushing-partial-updates","link":"#pushing-partial-updates","children":[]},{"level":2,"title":"Passing Variables to Partials","slug":"passing-variables-to-partials","link":"#passing-variables-to-partials","children":[]}],"relativePath":"4.x/cms/ajax/update-partials.md","filePath":"4.x/cms/ajax/update-partials.md"}'),r={name:"4.x/cms/ajax/update-partials.md"};function u(d,a,g,k,h,m){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Updating Partials",-1)),n(e),a[1]||(a[1]=i(`<p>When a handler executes it may prepare partials that are updated on the page, either by pushing or pulling, which can be rendered with some supplied variables.</p><h2 id="pulling-partial-updates"><a href="#pulling-partial-updates" class="header-anchor">#</a> Pulling Partial Updates</h2><p>The client browser may request partials to be updated from the server when it performs an AJAX request, which is considered <em>pulling a content update</em>.</p><p>Using the <a href="./../../markup/tag/partial.html"><code>{% partial %}</code> tag</a>, the following code renders the <strong>mytime</strong> partial inside a <code>#myDiv</code> element on the page when calling the <code>onRefreshTime</code> <a href="./handlers.html">event handler</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <a href="./attributes-api.html">data attributes API</a> uses the <code>data-request-update</code> attribute.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mytime: &#39;#myDiv&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <a href="./javascript-api.html">JavaScript API</a> uses the <code>update</code> configuration option:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token comment">// JavaScript API</span>
jax<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;#mybutton&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;onRefreshTime&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">mytime</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="self-updating-partials"><a href="#self-updating-partials" class="header-anchor">#</a> Self-Updating Partials</h3><p>The <a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> tag</a> is dedicated to rendering AJAX partials.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>When using this tag, the contents are wrapped in a container for you, so you can update the partial by name alone. Simply pass the <code>true</code> value instead of a container selector.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mytime: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You may also use the partial name <code>_self</code> for updating a partial from within itself.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">_self</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>See the <a href="./../../markup/tag/ajax-partial.html">AJAX Partial Twig Tag article</a> to learn more about the <code>{% ajaxPartial %}</code> tag.</p></div><h3 id="global-partial-updates"><a href="#global-partial-updates" class="header-anchor">#</a> Global Partial Updates</h3><p>In some cases, such as with <a href="./features/flash-messages.html">flash messages</a>, you may wish to include a specific partial update with every response. To merge an update definition with every AJAX request, add the <code>ajax-request-update</code> meta tag in the head section of the page, and set the content attribute to an update definition.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ajax-request-update<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ flash-messages: true }<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="update-definition"><a href="#update-definition" class="header-anchor">#</a> Update Definition</h2><p>The definition of what should be updated is specified as a JSON-like object where:</p><ul><li>the left side (key) is the <strong>partial name</strong></li><li>the right side (value) is the <strong>target element</strong> to update</li></ul><p>The following will request to update the <code>#myDiv</code> element with <strong>mypartial</strong> contents.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">mypartial</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>The selector must start with a <code>#</code> or <code>.</code> character to be valid.</p></div><p>Multiple partials are separated by commas.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">firstpartial</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">secondpartial</span><span class="token operator">:</span> <span class="token string">&#39;#otherDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>If the partial name contains a slash or a dash, it is important to &#39;quote&#39; the left side.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/mypartial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;my-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>The target element will always be on the right side since it can also be a HTML element in JavaScript.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/mypartial&#39;</span><span class="token operator">:</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;myDiv&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
</code></pre></div><h3 id="appending-and-prepending-content"><a href="#appending-and-prepending-content" class="header-anchor">#</a> Appending and Prepending Content</h3><p>If the selector string is prepended with the <code>@</code> symbol, the content received from the server will be appended to the element, instead of replacing the existing content.</p><p>If the selector string is prepended with the <code>^</code> symbol, the content will be prepended instead.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/append-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;@#myDiv&#39;</span> <span class="token punctuation">}</span>

<span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/prepend-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;^#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>Alternatively, you may add the <code>data-ajax-update-mode</code> attribute to the target element.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-ajax-update-mode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>append<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-ajax-update-mode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>prepend<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="using-custom-html-selectors"><a href="#using-custom-html-selectors" class="header-anchor">#</a> Using Custom HTML Selectors</h3><p>If the selector string begins with an <code>=</code> symbol, then you can use any custom HTML selector to target an element.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/append&#39;</span><span class="token operator">:</span> <span class="token string">&#39;=[data-field-name=&quot;address&quot;]&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><h2 id="pushing-partial-updates"><a href="#pushing-partial-updates" class="header-anchor">#</a> Pushing Partial Updates</h2><p>Comparatively, <a href="./handlers.html">AJAX handlers</a> can push content updates to the client-side browser from the server-side. To push an update the handler returns an array where the key is a HTML element to update (using a simple CSS selector) and the value is the content to update.</p><div class="custom-block aside"><p>The key name must start with an identifier <code>#</code> or class <code>.</code> character to trigger a content update.</p></div><p>The following example will update an element on the page with the id <strong>myDiv</strong> using the contents found inside the partial <strong>mypartial</strong>. The <code>onRefreshTime</code> handler calls the <code>renderPartial</code> method to render the partial contents in PHP.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRefreshTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#myDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypartial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="passing-variables-to-partials"><a href="#passing-variables-to-partials" class="header-anchor">#</a> Passing Variables to Partials</h2><p>Depending on the execution context, an <a href="./handlers.html">AJAX event handler</a> makes variables available to partials differently.</p><ul><li>Use <code>$this[]</code> inside a page or layout <a href="./../themes/themes.html">PHP section</a>.</li><li>Use <code>$this-&gt;page[]</code> inside a <a href="./../themes/components.html">component class</a>.</li><li>Use <code>$this-&gt;vars[]</code> in the <a href="./../../extend/system/controllers.html">backend area</a>.</li></ul><p>These examples will provide the <strong>result</strong> variable to a partial for each context:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// From page or layout PHP code section</span>
<span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a component class</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a backend controller or widget</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>This value can then be accessed using Twig in the partial:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Hello world! --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div>`,53))])}const y=p(r,[["render",u]]);export{f as __pageData,y as default};
